#!/bin/bash

# Stop the script immediately if a command fails.
set -e

# Install curl
apt-get update
apt-get install -y curl

# Wait until the server has generated its node-token.
# /vagrant is the shared directory between the host and both VMs.
until [ -s /vagrant/node-token ]; do
    echo "Waiting for the K3s server token..."
    sleep 2
done

# Read the authentication token generated by the server.
K3S_TOKEN=$(cat /vagrant/node-token)

# Install K3s as a worker (agent) and join the server.
# K3S_URL: API endpoint of the K3s server.
# K3S_TOKEN: authentication token used to join the cluster.
# --node-ip: worker's fixed IP address.
# --flannel-iface: interface used for inter-node networking.
curl -sfL https://get.k3s.io | \
    K3S_URL=https://192.168.56.110:6443 \
    K3S_TOKEN="$K3S_TOKEN" \
    sh -s - agent \
    --node-ip 192.168.56.111 \
    --flannel-iface eth1
